import { useEffect, useRef, useState } from "react";
import type { ReactNode } from "react";
import { LayoutAnimation, Pressable, StyleSheet, Text, View } from "react-native";
import type { StyleProp, TextStyle, ViewProps, ViewStyle } from "react-native";
import { metrics, useTokens } from "../lib/rn-tokens";

export interface ExpandingButtonGroupItem {
  id: string;
  label: string;
  icon: ReactNode;
  /** Return false to cancel the confirmation. A promise keeps the button pending. */
  onSelect?: () => void | boolean | Promise<void | boolean>;
  /** Shown briefly after the action succeeds, such as "Archived". */
  doneLabel?: string;
  tone?: "neutral" | "danger";
  disabled?: boolean;
}

export interface ExpandingButtonGroupProps extends Omit<ViewProps, "children"> {
  items: readonly ExpandingButtonGroupItem[];
  label: string;
  size?: "sm" | "md";
  onAction?: (id: string) => void;
  /** Milliseconds the done label shows. */
  confirmDuration?: number;
  /** Extend the inner, named parts of the group: button or buttonText. The React Native counterpart of `classNames`. */
  styles?: {
    button?: StyleProp<ViewStyle>;
    buttonText?: StyleProp<TextStyle>;
  };
}

/** Icon buttons: the first press expands one to show what it does, the second runs it. */
export function ExpandingButtonGroup({ items, label, size = "md", onAction, confirmDuration = 1400, style, styles: parts, ...props }: ExpandingButtonGroupProps) {
  const tokens = useTokens();
  const [expanded, setExpanded] = useState<string | null>(null);
  const [done, setDone] = useState<string | null>(null);
  const timer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  const height = size === "sm" ? 32 : 40;

  useEffect(() => () => clearTimeout(timer.current), []);

  async function press(item: ExpandingButtonGroupItem) {
    LayoutAnimation.configureNext(LayoutAnimation.Presets.easeInEaseOut);
    if (expanded !== item.id) return setExpanded(item.id);
    const result = await item.onSelect?.();
    if (result === false) return setExpanded(null);
    onAction?.(item.id);
    setDone(item.id);
    clearTimeout(timer.current);
    timer.current = setTimeout(() => {
      LayoutAnimation.configureNext(LayoutAnimation.Presets.easeInEaseOut);
      setDone(null);
      setExpanded(null);
    }, confirmDuration);
  }

  return (
    <View {...props} accessibilityRole="toolbar" accessibilityLabel={label} style={[local.root, { borderColor: tokens.border, backgroundColor: tokens.surfaceMuted }, style]}>
      {items.map((item) => {
        const open = expanded === item.id;
        const danger = item.tone === "danger";
        return (
          <Pressable
            key={item.id}
            accessibilityRole="button"
            accessibilityLabel={item.label}
            accessibilityState={{ expanded: open, disabled: item.disabled }}
            disabled={item.disabled}
            onPress={() => press(item)}
            style={[local.button, { height, minWidth: height, backgroundColor: open ? tokens.surface : "transparent" }, parts?.button]}
          >
            {item.icon}
            {open ? <Text style={[{ color: danger ? tokens.danger : tokens.foreground, fontSize: metrics.text.sm, fontWeight: "500" }, parts?.buttonText]}>{done === item.id ? (item.doneLabel ?? item.label) : item.label}</Text> : null}
          </Pressable>
        );
      })}
    </View>
  );
}

const local = StyleSheet.create({
  root: { flexDirection: "row", alignSelf: "flex-start", gap: 2, padding: 3, borderWidth: 1, borderRadius: 999 },
  button: { flexDirection: "row", alignItems: "center", justifyContent: "center", gap: 6, paddingHorizontal: 10, borderRadius: 999 },
});

export default ExpandingButtonGroup;

import { useColorScheme } from "react-native";

/** The Manicat UI design tokens as React Native values. Same names and meaning as registry/foundation.css. */
export interface ManicatTokens {
  background: string;
  surface: string;
  surfaceMuted: string;
  foreground: string;
  textSecondary: string;
  textMuted: string;
  border: string;
  borderStrong: string;
  accent: string;
  accentStrong: string;
  accentSubtle: string;
  success: string;
  warning: string;
  danger: string;
  controlOn: string;
  controlTrack: string;
  controlThumb: string;
  controlThumbOn: string;
  /** Four distinguishable colours for chart series, the counterpart of --series-1 to --series-4. */
  series: [string, string, string, string];
}

export const lightTokens: ManicatTokens = {
  background: "#ffffff",
  surface: "#ffffff",
  surfaceMuted: "#f6f6f6",
  foreground: "#1b1b1b",
  textSecondary: "#6e6e6e",
  textMuted: "#8f8f8f",
  border: "#ebebeb",
  borderStrong: "#c9c9c9",
  accent: "#4a4a4a",
  accentStrong: "#303030",
  accentSubtle: "rgba(74, 74, 74, 0.1)",
  success: "#1f8a4c",
  warning: "#b8741a",
  danger: "#d03b3b",
  controlOn: "#2c2c2c",
  controlTrack: "#e2e2e2",
  controlThumb: "#ffffff",
  controlThumbOn: "#ffffff",
  series: ["#1f7dcf", "#7128a5", "#e58f00", "#009e84"],
};

export const darkTokens: ManicatTokens = {
  background: "#2b2b2b",
  surface: "#303030",
  surfaceMuted: "#3c3c3c",
  foreground: "#f1f1f1",
  textSecondary: "#c4c4c4",
  textMuted: "#a0a0a0",
  border: "#454545",
  borderStrong: "#5c5c5c",
  accent: "#cfcfcf",
  accentStrong: "#e6e6e6",
  accentSubtle: "rgba(207, 207, 207, 0.13)",
  success: "#5fd48a",
  warning: "#f0b95c",
  danger: "#ff8a80",
  controlOn: "#ececec",
  controlTrack: "#515151",
  controlThumb: "#f4f4f4",
  controlThumbOn: "#2b2b2b",
  series: ["#55adff", "#9c37be", "#e66e00", "#00a861"],
};

/** Shape and rhythm shared by every component, in density-independent pixels. */
export const metrics = {
  radiusControl: 18,
  radiusPill: 9999,
  controlHeight: { sm: 36, md: 44, lg: 50 },
  space: { 1: 4, 2: 8, 3: 12, 4: 16, 5: 20 },
  text: { xs: 12, sm: 14, lg: 18 },
} as const;

/** The tokens for the device's current colour scheme. Wrap the app in your own provider if you manage the theme yourself. */
export function useTokens(): ManicatTokens {
  return useColorScheme() === "dark" ? darkTokens : lightTokens;
}
